CREATE POLICY "company_documents_storage_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'company-documents' AND public.is_org_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "company_documents_storage_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'company-documents' AND public.is_org_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "company_documents_storage_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'company-documents' AND public.is_org_member(((storage.foldername(name))[1])::uuid)) WITH CHECK (bucket_id = 'company-documents' AND public.is_org_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "company_documents_storage_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'company-documents' AND public.is_org_member(((storage.foldername(name))[1])::uuid));